CREATE TABLE knowledge_document(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant,title varchar(200) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id));
CREATE TABLE knowledge_chunk(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,document_id uuid NOT NULL,ordinal integer NOT NULL,content text NOT NULL CHECK(length(content)<=1200),embedding double precision[] NOT NULL,UNIQUE(tenant_id,document_id,ordinal),FOREIGN KEY(tenant_id,document_id) REFERENCES knowledge_document(tenant_id,id));
CREATE TABLE ai_usage(tenant_id uuid NOT NULL REFERENCES tenant,usage_date date NOT NULL,calls integer NOT NULL CHECK(calls>=0),PRIMARY KEY(tenant_id,usage_date));
CREATE TABLE copy_draft(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant,sku_id uuid NOT NULL,content text NOT NULL,status text NOT NULL DEFAULT 'PENDING_REVIEW' CHECK(status IN('PENDING_REVIEW','APPROVED','REJECTED')),created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(tenant_id,sku_id) REFERENCES sku(tenant_id,id));
